applyCoupon(id: number, couponCode: unknown): Order {
  // REQ-13: request body validation
  if (typeof couponCode !== "string" || couponCode.trim() === "") {
    throw badRequest("INVALID_REQUEST", "couponCode is required");
  }
  // REQ-01: normalize
  const code = couponCode.trim().toUpperCase();

  // REQ-04: order exists
  const order = this.orders.findById(id);
  if (!order) throw notFound("ORDER_NOT_FOUND", `order ${id} not found`);

  // REQ-04: status PENDING
  if (order.status !== "PENDING") throw conflict("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);

  // REQ-10: one coupon per order
  if (order.couponCode !== null) throw conflict("COUPON_ALREADY_APPLIED", `order ${id} already has a coupon`);

  // REQ-01: coupon exists
  const coupon = this.coupons.findByCode(code);
  if (!coupon) throw notFound("COUPON_NOT_FOUND", `coupon ${code} not found`);

  // REQ-02: active
  if (coupon.status !== "ACTIVE") throw badRequest("COUPON_INACTIVE", `coupon ${code} is not active`);

  // REQ-03: validity window
  const now = this.clock();
  const nowMs = now.getTime();
  if (nowMs < Date.parse(coupon.validFrom)) throw badRequest("COUPON_NOT_YET_VALID", ...);
  if (nowMs >= Date.parse(coupon.validUntil)) throw badRequest("COUPON_EXPIRED", ...);

  // REQ-11: usage limit
  if (coupon.usageLimit !== null && coupon.usedCount >= coupon.usageLimit) throw badRequest("COUPON_USAGE_EXHAUSTED", ...);

  // REQ-05: minimum
  if (order.amountCents < coupon.minAmountCents) throw badRequest("MINIMUM_NOT_MET", ...);

  // REQ-06/07/08/09: discount
  let discount = coupon.type === "FIXED" ? coupon.value : Math.floor((order.amountCents * coupon.value) / 100);
  if (coupon.maxDiscountCents !== null) discount = Math.min(discount, coupon.maxDiscountCents);
  discount = Math.min(discount, order.amountCents);
  const finalAmount = order.amountCents - discount;

  // REQ-12: persist atomically
  this.orders.applyCoupon(id, code, discount, finalAmount, now.toISOString());

  return this.get(id);
}
