  it("AC-10: trims and uppercases the coupon code", () => {
    const { app } = makeApp();
    seedCoupon(app, { code: "SAVE20" });
    const order = seedOrder(app, 10000);

    const res = apply(app, order.id, " save20 ");
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ couponCode: "SAVE20" });
  });
});

describe("apply-coupon validation and error precedence", () => {
  it("rejects a missing, non-string, or blank couponCode with INVALID_REQUEST", () => {
    const { app } = makeApp();
    const order = seedOrder(app);

    for (const body of [{}, { couponCode: 123 }, { couponCode: "   " }, { couponCode: null }]) {
      const res = app.request("POST", `/orders/${order.id}/apply-coupon`, body);
      expect(res.status).toBe(400);
      expect((res.body as any).error.code).toBe("INVALID_REQUEST");
    }
  });

  it("returns ORDER_NOT_FOUND for an unknown order", () => {
    const { app } = makeApp();
    seedCoupon(app);

    const res = apply(app, 999, "SAVE20");
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("ORDER_NOT_FOUND");
  });

  it("returns ORDER_NOT_PENDING for a paid order", () => {
    const { app } = makeApp();
    seedCoupon(app);
    const order = seedOrder(app);
    app.request("POST", `/orders/${order.id}/pay`);

    const res = apply(app, order.id, "SAVE20");
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("returns ORDER_NOT_PENDING for a cancelled order", () => {
    const { app } = makeApp();
    seedCoupon(app);
    const order = seedOrder(app);
    app.request("POST", `/orders/${order.id}/cancel`);

    const res = apply(app, order.id, "SAVE20");
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("returns COUPON_NOT_FOUND for an unknown coupon", () => {
    const { app } = makeApp();
    const order = seedOrder(app);

    const res = apply(app, order.id, "NOPE");
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("COUPON_NOT_FOUND");
  });

  it("returns COUPON_INACTIVE for a disabled coupon", () => {
    const { app } = makeApp();
    seedCoupon(app, { status: "DISABLED" });
    const order = seedOrder(app);

    const res = apply(app, order.id, "SAVE20");
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_INACTIVE");
  });

  it("returns COUPON_NOT_YET_VALID before validFrom and succeeds at validFrom", () => {
    const { app, setNow } = makeApp();
    seedCoupon(app, { validFrom: "2026-12-01T00:00:00Z", validUntil: "2027-01-01T00:00:00Z" });
    const order = seedOrder(app);

    const early = apply(app, order.id, "SAVE20");
    expect(early.status).toBe(400);
    expect((early.body as any).error.code).toBe("COUPON_NOT_YET_VALID");

    setNow("2026-12-01T00:00:00Z");
    expect(apply(app, order.id, "SAVE20").status).toBe(200);
  });

  it("returns COUPON_EXPIRED at validUntil and after", () => {
    const { app, setNow } = makeApp();
    seedCoupon(app, { validFrom: "2026-01-01T00:00:00Z", validUntil: "2026-11-01T00:00:00Z" });
    const order = seedOrder(app);

    setNow("2026-11-01T00:00:00Z");
    const atEnd = apply(app, order.id, "SAVE20");
    expect(atEnd.status).toBe(400);
    expect((atEnd.body as any).error.code).toBe("COUPON_EXPIRED");

    setNow("2026-11-02T00:00:00Z");
    const after = apply(app, order.id, "SAVE20");
    expect(after.status).toBe(400);
    expect((after.body as any).error.code).toBe("COUPON_EXPIRED");
  });

  it("returns COUPON_USAGE_EXHAUSTED once the limit is reached", () => {
    const { app } = makeApp();
    seedCoupon(app, { usageLimit: 1 });
    const first = seedOrder(app);
    const second = seedOrder(app);

    expect(apply(app, first.id, "SAVE20").status).toBe(200);
    const res = apply(app, second.id, "SAVE20");
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_USAGE_EXHAUSTED");
  });

  it("returns MINIMUM_NOT_MET below the coupon minimum", () => {
    const { app } = makeApp();
    seedCoupon(app, { minAmountCents: 20000 });
    const order = seedOrder(app, 10000);

    const res = apply(app, order.id, "SAVE20");
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("MINIMUM_NOT_MET");
  });

  it("checks body validation before order state", () => {
    const { app } = makeApp();

    const res = app.request("POST", "/orders/999/apply-coupon", { couponCode: "   " });
    expect((res.body as any).error.code).toBe("INVALID_REQUEST");
  });

  it("checks order state before coupon state", () => {
    const { app } = makeApp();
    const order = seedOrder(app);
    app.request("POST", `/orders/${order.id}/pay`);

    const res = apply(app, order.id, "DOES_NOT_EXIST");
    expect((res.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("leaves the database unchanged on every rejection", () => {
    const { app } = makeApp();
    seedCoupon(app, { minAmountCents: 20000 });
    const order = seedOrder(app, 10000);

    expect(apply(app, order.id, "SAVE20").status).toBe(400);
    expect(app.db.prepare("SELECT COUNT(*) AS n FROM coupon_redemptions").get()).toEqual({ n: 0 });
    expect((app.request("GET", `/orders/${order.id}`).body as any)).toMatchObject({
      discountCents: 0,
      finalAmountCents: 10000,
      couponCode: null,
    });
  });
});

describe("apply-coupon integration", () => {
  it("returns the same body as GET /orders/:id (AC-14)", () => {
    const { app } = makeApp();
    seedCoupon(app);
    const order = seedOrder(app);

    const applied = apply(app, order.id, "SAVE20");
    expect(applied.status).toBe(200);
    expect(applied.body).toEqual(app.request("GET", `/orders/${order.id}`).body);
    expect(applied.body).toMatchObject({ id: order.id, status: "PENDING", couponCode: "SAVE20" });
  });

  it("rejects a second coupon with COUPON_ALREADY_APPLIED and keeps amounts (AC-08)", () => {
    const { app } = makeApp();
    seedCoupon(app);
    const order = seedOrder(app);

    expect(apply(app, order.id, "SAVE20").status).toBe(200);
    const second = apply(app, order.id, "SAVE20");
    expect(second.status).toBe(409);
    expect((second.body as any).error.code).toBe("COUPON_ALREADY_APPLIED");
    expect(app.request("GET", `/orders/${order.id}`).body).toMatchObject({
      discountCents: 2000,
      finalAmountCents: 8000,
      couponCode: "SAVE20",
    });
  });

  it("increments usedCount and records a redemption row (AC-09)", () => {
    const { app } = makeApp();
    seedCoupon(app);
    const order = seedOrder(app);

    expect(apply(app, order.id, "SAVE20").status).toBe(200);

    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 1 });
    expect(
      app.db
        .prepare("SELECT order_id, coupon_code, discount_cents FROM coupon_redemptions WHERE order_id = ?")
        .get(order.id),
    ).toMatchObject({ order_id: order.id, coupon_code: "SAVE20", discount_cents: 2000 });
  });
});

